cat > probe_typed_test.go <<'EOF'
package main

import (
	"errors"
	"strings"
	"testing"
	"time"
)

func TestProbeTypedError(t *testing.T) {
	store := NewStore(time.Minute)
	_, err := store.Get("nope")
	if err == nil {
		t.Fatal("expected error")
	}
	var le *LookupError
	if !errors.As(err, &le) {
		t.Fatalf("error %T does not unwrap to *LookupError", err)
	}
	if le.ID != "nope" {
		t.Fatalf("LookupError.ID = %q, want nope", le.ID)
	}
	if !strings.Contains(le.Error(), "nope") {
		t.Fatalf("Error() must contain the id: %q", le.Error())
	}
	if !errors.Is(err, ErrNotFound) {
		t.Fatal("ErrNotFound compatibility broken")
	}
	// Successful lookups are unaffected.
	store.Create("ok", "u")
	if _, err := store.Get("ok"); err != nil {
		t.Fatalf("good lookup: %v", err)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_typed_test.go ; exit $rc

